
(function () {
  var BBL = {
    logo: "data:image/jpeg;base64,",
    proposal: "data:image/jpeg;base64,",
    payment: "data:image/jpeg;base64,",
    homedepot: "data:image/jpeg;base64,"
  };

  var BBF = [
    { tab: "Proposals", icon: "ti-writing",
      desc: "Tell Buddy the scope and customer name. It generates a professional PDF \u2014 with your logo, line items, and exclusions \u2014 ready to send. Client says yes? Buddy converts it into a project automatically.",
      title: "Win jobs with clean proposals",
      body: "Builder Buddy generates branded proposal PDFs in seconds. Your logo, your line items, your exclusions \u2014 all formatted and sent straight to the client. When they say yes, Buddy turns the proposal into a live project.",
      msgs: [
        { o: 1, t: "Create a proposal for Smith Properties \u2014 framing and drywall" },
        { o: 0, t: "Here\u2019s your proposal:\n\u2022 Customer: Smith Properties\n\u2022 Proposal #: PROP-004\n\u2022 Line items:\n  - Framing: $12,000.00\n  - Drywall: $8,200.00\n\u2022 Total: $20,200.00\n\u2022 Valid until: 2026-06-17\n\u2022 Exclusions: Finish materials to be provided by owner.\nConfirm?" },
        { o: 1, t: "confirm" },
        { o: 0, t: "\u2705 PROP-004 created for Smith Properties.\nTotal: $20,200.00 | Valid until: 2026-06-17\nPDF sent.", pdf: "PROP-004_Smith.pdf", pk: "proposal" }
      ]
    },
    { tab: "Expenses", icon: "ti-receipt",
      desc: "Snap a photo of a receipt or just say what you spent. Buddy reads the receipt and records it to the right project automatically.",
      title: "Log expenses in seconds",
      body: "Take a photo of any receipt and send it to Buddy. It reads the vendor, amount, and date, matches it to the right budget category, and logs it \u2014 all without you typing a thing.",
      msgs: [
        { o: 1, t: "Lumber for glencoe", img: "homedepot" },
        { o: 0, t: "Here\u2019s what I\u2019ll log:\n\u2022 Amount: $342.17 \u2014 Expense\n\u2022 Project: glencoe\n\u2022 Vendor: Home Depot\n\u2022 Category: Rough Structure (auto-suggested)\n\u2022 Payment: \u2753 required\n\u2022 Date: 2026-05-18\nReply: cash, check, wire, or card to confirm." },
        { o: 1, t: "card" },
        { o: 0, t: "\u2705 Transaction logged\n\u2022 $342.17 \u2014 Home Depot\n\u2022 Rough Structure \u00b7 Glencoe\n\u2022 Credit Card \u00b7 May 18" }
      ]
    },
    { tab: "Budget", icon: "ti-table",
      desc: "Set up a project budget once. Every expense you log is tracked against it \u2014 so you always know where you stand without opening a spreadsheet.",
      title: "Budgets that stay up to date",
      body: "Every transaction you log is tracked against your project budget in real time. Ask Buddy how much is left on any line and get an instant answer \u2014 no spreadsheet required.",
      msgs: [
        { o: 1, t: "How much budget left on glencoe?" },
        { o: 0, t: "Glencoe \u2014 Remaining Budget:\n\n\u2022 Framing: $12,000 \u00b7 $9,400 spent \u2192 $2,600 left\n\u2022 Drywall: $8,000 \u00b7 $8,340 spent \u2192 \u26a0\ufe0f $340 over\n\u2022 Plumbing: $6,500 \u00b7 $2,100 spent \u2192 $4,400 left\n\u2022 Labor: $18,000 \u00b7 $12,450 spent \u2192 $5,550 left\n\nTotal remaining: $12,210" }
      ]
    },
    { tab: "Labor", icon: "ti-clock-hour-4",
      desc: "Tell Buddy who worked and for how long. It logs the hours, calculates pay, and keeps a running total of what you owe each worker.",
      title: "Track worker hours",
      body: "Tell Buddy who worked and for how long. It looks up each worker\u2019s rate, calculates what they\u2019re owed, and logs it as a pending payment \u2014 so you never lose track of what you owe.",
      msgs: [
        { o: 1, t: "Mike and Carlos worked 9 hours on glencoe today" },
        { o: 0, t: "Logged:\n\u2022 Mike Rodriguez \u2014 9 hrs \u2014 $405.00 (hourly $45/hr) \u2014 Entry ID: TS-0041\n\u2022 Carlos Vega \u2014 9 hrs \u2014 $342.00 (hourly $38/hr) \u2014 Entry ID: TS-0042\n\nRecorded as pending payment. Let me know if this was already paid." }
      ]
    },
    { tab: "Pay requests", icon: "ti-file-invoice",
      desc: "Ask Buddy to create a pay request and it generates a clean PDF \u2014 with your company info, line items, and totals \u2014 ready to send to your GC.",
      title: "Send payment requests fast",
      body: "Buddy generates professional pay request PDFs with your letterhead, line items, and totals \u2014 and sends them via WhatsApp. When payment comes in, mark it paid in one message.",
      msgs: [
        { o: 1, t: "Send a pay request to Smith Properties for framing, $8,000" },
        { o: 0, t: "Here\u2019s what I\u2019ll send:\n\u2022 Project: glencoe\n\u2022 Client: Smith Properties\n\u2022 Pay Request #: PR-001\n\u2022 Line items:\n  - Framing: $8,000.00\n\u2022 Total: $8,000.00\nConfirm?" },
        { o: 1, t: "confirm" },
        { o: 0, t: "\u2705 Pay Request PR-001 Sent\n\nProject: Glencoe\nClient: Smith Properties\n\nLine Items:\n  \u2022 Framing: $8,000.00\n\nTotal: $8,000.00", pdf: "PR-001_Glencoe.pdf", pk: "payment" }
      ]
    },
    { tab: "Reports & queries", icon: "ti-chart-bar",
      desc: "Ask anything about your jobs in plain English. Buddy answers instantly and can generate detailed labor payment reports as Excel files.",
      title: "See how each job is performing",
      body: "Ask Buddy anything \u2014 margins, remaining budget, who you owe \u2014 and get an instant answer. Or generate a full labor payment report as an Excel file, broken down by worker or by project.",
      msgs: [
        { o: 1, t: "What\u2019s my margin on glencoe?" },
        { o: 0, t: "Glencoe \u2014 Margin Summary:\n\nCustomer total: $68,500.00\nInternal budget: $54,200.00\nTotal spent: $32,290.00\n\nMargin: $14,300.00 (20.9%)\nRemaining internal: $21,910.00" },
        { o: 1, t: "Generate labor report for this week" },
        { o: 0, t: "Which view?\n1. Per worker (one tab per worker)\n2. Per project (one tab per project)" },
        { o: 1, t: "per worker" },
        { o: 0, t: "\ud83d\udcca Labor report sent.", xl: "Labor_Week_May2026.xlsx" }
      ]
    },
    { tab: "Voice", icon: "ti-microphone",
      desc: "Driving between sites? Hands covered in mud? Send a voice note. Buddy listens, understands what you need, and gets it done.",
      title: "Use your voice, hands-free",
      body: "On a job site with dirty hands, or driving between sites? Send a voice note. Buddy understands what you need and handles it \u2014 same as if you typed it.",
      msgs: [
        { o: 1, voice: 1 },
        { o: 0, t: "Here\u2019s what I\u2019ll log:\n\u2022 Amount: $1,850.00 \u2014 Expense\n\u2022 Project: glencoe\n\u2022 Vendor: Ready Mix Co\n\u2022 Category: Concrete (auto-suggested)\n\u2022 Payment: cash\n\u2022 Date: 2026-05-18\nConfirm?" },
        { o: 1, t: "confirm" },
        { o: 0, t: "\u2705 Transaction logged\n\u2022 $1,850.00 \u2014 Ready Mix Co\n\u2022 Concrete \u00b7 Glencoe\n\u2022 Cash \u00b7 May 18" }
      ]
    }
  ];

  // ── lightbox ──
  var ov = document.getElementById('bb-ov');
  var oi = document.getElementById('bb-oi');
  document.getElementById('bb-cls').onclick = function () { ov.classList.remove('bb-on'); };
  ov.onclick = function (e) { if (e.target === ov) ov.classList.remove('bb-on'); };

  function bbShow(k) { oi.src = BBL[k]; ov.classList.add('bb-on'); }

  function ts() {
    var d = new Date();
    return d.getHours() + ':' + String(d.getMinutes()).padStart(2, '0');
  }

  function bbRender(idx) {
    document.querySelectorAll('.bb-tab').forEach(function (t, i) { t.classList.toggle('bb-on', i === idx); });
    var f = BBF[idx];
    var descEl = document.getElementById('bb-desc');
    var titleEl = document.getElementById('bb-ctitle');
    var bodyEl = document.getElementById('bb-cbody');
    if (descEl) descEl.textContent = f.desc;
    if (titleEl) titleEl.textContent = f.title;
    if (bodyEl) bodyEl.textContent = f.body;
    var chat = document.getElementById('bb-chat');
    chat.innerHTML = '';
    f.msgs.forEach(function (m, i) {
      setTimeout(function () {
        var d = document.createElement('div');
        d.className = 'bb-bub ' + (m.o ? 'bb-out' : 'bb-in');
        var h = '';
        if (m.voice) {
          h = '<div style="display:flex;align-items:center;gap:8px">'
            + '<i class="ti ti-microphone" style="font-size:18px;color:#1D9E75"></i>'
            + '<div style="flex:1;height:3px;background:#bbb;border-radius:2px"></div>'
            + '<span style="font-size:11px;color:#888">0:09</span></div>';
        } else if (m.img) {
          h = '<img class="bb-rimg" src="' + BBL[m.img] + '" alt="receipt" onclick="bbShow(\'' + m.img + '\')">';
        }
        if (m.t) {
          var safe = m.t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
          h += '<div style="white-space:pre-line;margin-top:' + (m.img ? '4' : '0') + 'px">' + safe + '</div>';
        }
        if (m.pdf) {
          h += '<button class="bb-pill" onclick="bbShow(\'' + m.pk + '\')">'
            + '<i class="ti ti-file-type-pdf" style="color:#c0392b"></i>'
            + m.pdf + ' <span style="font-size:10px;color:#999;margin-left:2px">tap to preview</span></button>';
        }
        if (m.xl) {
          h += '<div class="bb-pill bb-xpill">'
            + '<i class="ti ti-file-spreadsheet" style="color:#217346"></i>' + m.xl + '</div>';
        }
        var ck = m.o ? '<i class="ti ti-checks" style="font-size:11px;color:#6aab6a"></i>' : '';
        h += '<div class="bb-time">' + ck + ' ' + ts() + '</div>';
        d.innerHTML = h;
        chat.appendChild(d);
        chat.scrollTop = chat.scrollHeight;
      }, i * 170);
    });
  }

  window.bbShow = bbShow;
  window.bbRender = bbRender;

  var tabsEl = document.getElementById('bb-tabs');
  BBF.forEach(function (f, i) {
    var b = document.createElement('button');
    b.className = 'bb-tab' + (i === 0 ? ' bb-on' : '');
    b.innerHTML = '<i class="ti ' + f.icon + '"></i> ' + f.tab;
    b.onclick = function () { bbRender(i); };
    tabsEl.appendChild(b);
  });

  var logoEl = document.getElementById('bb-logo');
  if (logoEl) logoEl.src = BBL.logo;

  bbRender(0);
})();
